        await pg.evaluate("HH.logout(); HH.ui.city = undefined; HH.ui.nearKm = undefined; HH.ui.geo = { lat: -34.6037, lng: -58.3816, acc: 50, at: HH.now(), city: 'Ciudad de Buenos Aires' }; HH.ui.geoStatus = 'ok'; HH.save(); HH.go('#cerca')"); await pg.wait_for_timeout(400)
        r = await pg.evaluate("JSON.stringify({sel: document.querySelector('.km-sel select').value, n: document.querySelectorAll('.pub-near-list .list-item').length, max: Math.max(0, ...[...document.querySelectorAll('.pub-near-list .list-item')].map(a => HH.distanceKm(HH.profileBySlug(a.getAttribute('href').split('.').pop()))))})")
        check('sin opción sin límite', await pg.evaluate("![...document.querySelectorAll('.km-sel option')].some(o => o.value === '0')"))
        check('radio 15 km por defecto '+r, '"sel":"15"' in r and __import__('json').loads(r)['max'] <= 15)
        await pg.select_option('.km-sel select', '100'); await pg.wait_for_timeout(400)
        n2 = await pg.evaluate("document.querySelectorAll('.pub-near-list .list-item').length")
        check('100 km muestra igual o más '+str(n2), n2 >= __import__('json').loads(r)['n'])
        await pg.evaluate("HH.ui.geo = null; HH.ui.geoStatus = 'off'; HH.ui.nearKm = undefined; HH.save()")
        # 22. Match: chat en vivo en lugar del número
        await pg.evaluate("HH.logout(); HH.login('u_c4'); HH.profileOf('u_vale').chatOnline = true; HH.save(); HH.go('#perfil.valentina')"); await pg.wait_for_timeout(400)
