        check('match: WhatsApp + Telegram, coordinar y chat', await pg.evaluate("!document.getElementById('pubWaNum') && !!document.querySelector('#modalBox .msg-split a.wa') && !!document.querySelector('#modalBox .msg-split a.tg[href*=\"t.me\"]') && !!document.querySelector('#modalBox [data-action=pubWaBook]:not([disabled])') && !!document.querySelector('#modalBox [data-action=pubWaChat]') && document.querySelector('#modalBox h3').textContent.startsWith('Contactá con')"))
